class Solution {
public:
    vector<int> zigzagTraversal(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<int> result;
        bool take = true;
        for (int r = 0; r < m; ++r) {
            if (r % 2 == 0) {
                for (int c = 0; c < n; ++c) {
                    if (take) result.push_back(grid[r][c]);
                    take = !take;
                }
            } else {
                for (int c = n - 1; c >= 0; --c) {
                    if (take) result.push_back(grid[r][c]);
                    take = !take;
                }
            }
        }
        return result;
    }
};

